mapper.select:
/** pe as 终止登记表：全部内容，条件：封闭式产品、未报送*/ /** ,pi as 产品投资交易：人民币总额，资产持仓数量*/ /** ,pp as 产品存续期交易：银行实际收益之和*/ /** ,ps as 产品的卖出投资交易数量，条件：已报送，卖出交易*/
/**检查结果*/ select prod_id prodid ,regist_seqno registseqno ,sended_counts regcounts ,abs(1- (total_amt+cny_amt)/ (case when (total_amt+CUSTOM_PROFIT+CUST_FEE_IN+MAN_FEE_IN+COU_FEE_IN+OTHER_FEE_IN+CUST_FEE_OUT)=0 then 1 else total_amt+CUSTOM_PROFIT+CUST_FEE_IN+MAN_FEE_IN+COU_FEE_IN+OTHER_FEE_IN+CUST_FEE_OUT end) ) diffrate1 ,asset_qty holdqty ,cny_amt cashamt ,profit bankprofit1 ,bank_profit bankprofit2 ,CUS_YEAR_YIELD custyield ,PRD_YEAR_YIELD prodyield ,abs( (profit+custom_profit-cny_amt)/(case when cny_amt=0 then 1 else cny_amt end) ) diffrate2 ,custom_profit custprofit1 from ( select ps.sended_counts ,pe.regist_seqno ,pe.prod_id ,ifnull(r.total_amt,0) total_amt ,ifnull(pi.cny_amt,0) cny_amt ,ifnull(pi.asset_qty,0) asset_qty ,ifnull(pe.CUSTOM_PROFIT,0) CUSTOM_PROFIT ,ifnull(pe.CUST_FEE_IN,0) CUST_FEE_IN ,ifnull(pe.MAN_FEE_IN,0) MAN_FEE_IN ,ifnull(pe.COU_FEE_IN,0) COU_FEE_IN ,ifnull(pe.OTHER_FEE_IN,0) OTHER_FEE_IN ,ifnull(pe.CUST_FEE_OUT,0) CUST_FEE_OUT ,ifnull(pe.profit,0) profit ,ifnull(pp.bank_profit,0) bank_profit ,ifnull(pe.CUS_YEAR_YIELD,0) CUS_YEAR_YIELD ,ifnull(pe.PRD_YEAR_YIELD,1) PRD_YEAR_YIELD from ( select e.* from chb_prd_end_sub e left join chb_prd_baseinfo i on e.prod_id=i.prod_id and i.status='E' where (e.SUBMIT_FEEDBACK_STATUS !='03' or e.SUBMIT_FEEDBACK_STATUS is null) AND i.RAISE_CCY='CNY' and i.CASH_PRIN_CCY='CNY' AND i.CASH_PROF_CCY='CNY' and i.operate_mode in ('01','02') AND i.VDATE>=date'2014-01-01' and e.status!='04' ) pe left join ( select prod_id,count(1) sended_counts from chb_invest_trade_sub where CUR_ASSET_TYPE in ('02','04','07','08') and SUBMIT_FEEDBACK_STATUS = '03' and status!='04' group by prod_id ) ps on pe.prod_id=ps.prod_id left join chb_prd_raisetot_sub r on pe.prod_id=r.prod_id left join ( select prod_id ,ifnull (sum( case when CUR_ASSET_TYPE in('01','03','05','08','10','12') then 0-cny_amt else CNY_AMT end ),0)cny_amt ,ifnull (sum( case when CUR_ASSET_TYPE in('01','03','05','06') then num when CUR_ASSET_TYPE in('02','04','07','08') then 0-num else 0 end ),0)asset_qty from chb_invest_trade_sub where status!='04' group by prod_id ) pi on pe.prod_id=pi.prod_id left join ( select prod_id,ifnull(sum(BANK_IMP_INT),0) bank_profit from chb_prd_deal_sub where status!='04' group by prod_id ) pp on pe.prod_id=pp.prod_id
null) or pe.REGIST_SEQNO in (
#{keys}
) t

/** pi as发行登记未报送的数据*/ select r.prod_id prodid ,r.REGIST_SEQNO registseqno,ifnull(pi.send_counts,0) regcounts from chb_prd_raisetot_sub r left join ( select prod_id ,count(1) send_counts from chb_prd_issue_sub where SUBMIT_FEEDBACK_STATUS ='03' and status!='04' group by prod_id ) pi on r.prod_id=pi.prod_id where (r.SUBMIT_FEEDBACK_STATUS !='03' or r.SUBMIT_FEEDBACK_STATUS is null)
null) or r.REGIST_SEQNO in (
#{keys}

/**未登记的资产*/ select ad.asset_code assetcode ,ai.reg_asset_count regcounts ,ad.prod_id prodid ,ad.asset_qty holdqty ,ad.max_price maxprice ,ad.min_price minprice from ( select prod_id ,asset_code ,sum( case when CUR_ASSET_TYPE in('01','03','05','06') then ifnull(num,0) when CUR_ASSET_TYPE in('02','04','07','08') then 0-ifnull(num,0) else 0 end )asset_qty ,round(max(cast(ifnull(CNY_AMT, 0) as float)/( case when num=0 then 1 else ifnull(num,1) end )),2) max_price ,round(min(cast(ifnull(CNY_AMT, 0) as float)/( case when num=0 then 1 else ifnull(num,1) end )),2) min_price from chb_invest_trade_sub where (SUBMIT_FEEDBACK_STATUS !='03' or SUBMIT_FEEDBACK_STATUS is null) and status!='04' and CUR_ASSET_TYPE in('01','02','03','04','05','06','07','08')
null) or REGIST_SEQNO in (
#{keys}
group by prod_id,asset_code ) ad left join ( select asset_code,count(1) reg_asset_count from chb_asset_info_sub a where a.SUBMIT_FEEDBACK_STATUS ='03' group by asset_code ) ai on ad.asset_code=ai.asset_code

select ad.asset_code assetcode ,ad.regist_seqno registseqno ,ad.vdate vdate ,ad.mdate mdate ,ad.pos_date posdate ,ad.diff_value diffrate1 ,ai.reg_asset_count regcounts from ( select p.regist_seqno ,p.asset_code ,i.vdate ,i.mdate ,p.pos_date ,round( ifnull(p.ISSUE_AMT,0)/( case when (ifnull(sp.POS_AMT,0)+ifnull(p.UNINVEST_CASH,0))=0 then 1 else (ifnull(sp.POS_AMT,0)+ifnull(p.UNINVEST_CASH,0)) end ) ,2)diff_value from chb_bot_ast_pos_sub p left join ( select sum(POS_AMT) POS_AMT,PLAN_ASSET_ID from chb_bot_ast_pos_sub GROUP by PLAN_ASSET_ID ) sp on sp.PLAN_ASSET_ID=p.PLAN_ASSET_ID left join chb_asset_info_sub i on p.asset_code=i.asset_code and i.SUBMIT_FEEDBACK_STATUS ='03' where (p.SUBMIT_FEEDBACK_STATUS !='03' or p.SUBMIT_FEEDBACK_STATUS is null)
) ad left join ( select asset_code,count(1) reg_asset_count from chb_asset_info_sub a where a.SUBMIT_FEEDBACK_STATUS ='03' group by asset_code ) ai on ad.asset_code=ai.asset_code WHERE 1=1
null) or REGIST_SEQNO in (
#{keys}

/**产品存续期交易：银行实际收益之和*/ select pm.termid ,pm.reportuuid registseqno ,ifnull(pp.bank_profit1,0) bankprofit1 ,ifnull(pm.bank_profit2,0) bankprofit2 from ( select DATE_FORMAT(#{checkdate,jdbcType=DATE},'%Y%m') termid ,sum(ifnull(BANK_IMP_INT,0)) bank_profit1 from chb_prd_deal_sub d left join chb_prd_baseinfo i on d.prod_id=i.prod_id and i.operate_mode in ('01','02') where d.status!='04' ) pp,( select d.termid,sum(bankprofit ) bank_profit2,m.reportuuid from chb_month_report_detail d left join chb_month_report m on d.termid = m.termid where d.termid=DATE_FORMAT(#{checkdate,jdbcType=DATE},'%Y%m') and d.propertycode in ( 'GMLCCP','SMLCCP') group by d.termid,m.reportuuid ) pm where pp.termid=pm.termid
null) or pm.reportuuid in (
#{keys}
